import hashlib, json
from pathlib import Path
root = Path('products/distribution/catalogue-referral')
names = ['item-4-operator-decision-pointer.json', 'item-4-release-binding.json', 'operator-handoff.md']
records = {}
for name in names:
    path = root / name
    data = path.read_bytes()
    records[name] = {'sha256': hashlib.sha256(data).hexdigest(), 'bytes': len(data)}
    if path.suffix == '.json':
        records[name]['public_record'] = json.loads(data)
report = {'scope': 'Readback of existing public item 4 records. Confirm any decision against the original authorized operator record for the exact draft before acting. A pointer or hash alone establishes no authorization, submission, or outcome.', 'records': records}
output = root / 'director-item-4-decision-provenance.json'
output.write_text(json.dumps(report, indent=2) + '\n', encoding='utf-8')
print(output.read_text(encoding='utf-8'))
